/* The Japanese romanizer's tables.
 *
 * Lifted byte for byte out of IBM's objects by
 * tools/rom/tables.py rather than retyped, and the code
 * that reads them is transcribed separately and reads them
 * exactly as the original does.
 *
 * All but two of them are bytes and have no relocation
 * inside them, so they really are bytes. The two that are
 * not are arrays of pointers to string literals, and those
 * are lifted by following the relocations and reading each
 * literal out of the COMDAT section it has to itself, so
 * the strings are taken rather than retyped as well.
 *
 * Each object's tables come out as one block with a pointer
 * into it per table, rather than as an array each, because
 * they were one block in the original and its own code does
 * not always stay inside the table it started in: the two
 * lead-byte tables are shorter than the range of lead bytes
 * the converter accepts, and a packed record can run on
 * past the end of its table. Laid out this way, whatever
 * such a read finds is what IBM's found.
 */

#include <stdint.h>

typedef struct { int32_t what; const char *how; }
    jajp_symbol;

/* dictman.obj
 * DictMan's tables: the dictionary hashes, the penalty and phrase
 * vectors, the number and reading tables, and the substitution tables
 * that make romaji out of English and kana out of romaji.
 */

